-- Generated by model/lib/sql/generate.mjs. Loads IMPORT FX Rate from cells/IMPORT FX Rate.csv in the folder of input cells. Two rows for one cell add up.
INSERT INTO "IMPORT FX Rate" ("Currency", "Years", "Months", v, ver, is_deleted) SELECT coalesce(k0."Currency", throwIf(isNull(k0."Currency"), 'cells name a member Currency does not have')), coalesce(k1."Years", throwIf(isNull(k1."Years"), 'cells name a member Years does not have')), coalesce(k2."Months", throwIf(isNull(k2."Months"), 'cells name a member Months does not have')), sum(toFloat64(c.value)), toUnixTimestamp64Micro(now64(6)), 0
FROM file('cells/IMPORT FX Rate.csv', 'CSVWithNames', '"Currency" String, "Years" String, "Months" String, "value" String') c LEFT JOIN "dim Currency" k0 ON k0.name = c."Currency" LEFT JOIN "dim Years" k1 ON k1.name = c."Years" LEFT JOIN "dim Months" k2 ON k2.name = c."Months"
GROUP BY ALL;
